		"colleagues.createDialog.rolePreset.frontend": "Frontend Development Engineer",
		"colleagues.createDialog.rolePreset.frontendDesc": "Owns frontend interface design and implementation, excels at component architecture, interaction details, responsive adaptation, and performance optimization, and keeps the experience stable. Continuously accumulates best practices.",
		"colleagues.createDialog.rolePreset.seniorDeveloper": "Senior Development Engineer",
		"colleagues.createDialog.rolePreset.seniorDeveloperDesc": "Owns complex module design and technical breakthroughs, excels at architectural trade-offs, performance optimization, high-concurrency processing, and difficult issue diagnosis, and ensures high-quality delivery. Continuously accumulates technical solutions.",
		"colleagues.createDialog.rolePreset.wechatMiniProgram": "WeChat Mini Program Developer",
		"colleagues.createDialog.rolePreset.wechatMiniProgramDesc": "Owns the WeChat Mini Program development framework and ecosystem, optimizes experience, and ensures smooth stability. Continuously accumulates Mini Program practices to build fluid WeChat-native applications.",
		"colleagues.createDialog.rolePreset.mobile": "Mobile Development Engineer",
		"colleagues.createDialog.rolePreset.mobileDesc": "Owns iOS, Android, and cross-platform app development, excels at interaction implementation, performance optimization, compatibility adaptation, and release quality assurance. Continuously accumulates mobile practices.",
		"colleagues.createDialog.rolePreset.aiEngineer": "AI Engineer",
		"colleagues.createDialog.rolePreset.aiEngineerDesc": "Owns LLM applications and agent development, excels at RAG, prompt engineering, workflow orchestration, and effect tuning, and drives AI capabilities into business scenarios. Continuously accumulates engineering practices.",
		"colleagues.createDialog.rolePreset.projectManager": "Project Manager",
		"colleagues.createDialog.rolePreset.projectManagerDesc": "Owns planning, scheduling, resource coordination, and risk management, excels at cross-team execution, progress tracking, and on-time delivery assurance. Continuously syncs milestone, risk, and resource changes.",
		"colleagues.createDialog.rolePreset.ui": "UI Designer",
		"colleagues.createDialog.rolePreset.uiDesc": "Owns interface visuals, component specifications, and design handoff, excels at layout, color, icons, and detail polish, and improves product quality. Continuously accumulates standards to keep the experience consistent.",
		"colleagues.createDialog.rolePreset.qa": "Engineering Tester",
		"colleagues.createDialog.rolePreset.qaDesc": "Owns test plans, case design, and defect tracking, excels at automated verification, risk identification, and launch quality assurance. Continuously accumulates test assets to improve delivery confidence.",
		"colleagues.createDialog.rolePreset.backendArchitect": "Backend Architect",
		"colleagues.createDialog.rolePreset.backendArchitectDesc": "Owns server-side architecture and system design, excels at high concurrency, high availability, layered decoupling, and performance tuning, and keeps systems stable and scalable. Continuously accumulates architecture solutions.",
		"colleagues.createDialog.rolePreset.productAdmin": "Product Administrator",
		"colleagues.createDialog.rolePreset.productAdminDesc": "Owns planning, scheduling, resource coordination, and risk management, excels at cross-team execution, progress tracking, and on-time delivery assurance. Continuously syncs milestone, risk, and resource changes.",
		"colleagues.createDialog.rolePreset.xiaohongshuOperator": "Xiaohongshu Operations Specialist",
		"colleagues.createDialog.rolePreset.xiaohongshuOperatorDesc": "Owns Xiaohongshu content operations and growth, excels at topic planning and viral titles, deeply understands the Xiaohongshu seeding ecosystem and recommendation mechanisms, creates high-engagement seeding content, and continuously accumulates operation methods.",
		"colleagues.createDialog.rolePreset.contentCreator": "Content Creation Specialist",
		"colleagues.createDialog.rolePreset.contentCreatorDesc": "Owns content planning and creative output, excels at topic discovery, graphic scripts, copywriting, and quality control, and improves communication results. Continuously accumulates creation methods.",
		"colleagues.createDialog.rolePreset.stockResearcher": "Stock Researcher",
		"colleagues.createDialog.rolePreset.stockResearcherDesc": "Owns individual stock research and market tracking, excels at financial report interpretation, valuation analysis, industry logic, and risk assessment, and outputs objective research conclusions. Continuously accumulates research frameworks.",
		"colleagues.createDialog.rolePreset.industryResearcher": "Industry Researcher",
		"colleagues.createDialog.rolePreset.industryResearcherDesc": "Owns industry research and trend analysis, excels at policy interpretation, competitive landscape analysis, data validation, and insight extraction to support business decisions. Continuously accumulates research methods.",
		"colleagues.createDialog.rolePreset.dataAnalyst": "Data Analyst",
		"colleagues.createDialog.rolePreset.dataAnalystDesc": "Owns metrics systems, dashboards, and thematic analysis, excels at finding business problems, validating hypotheses, and producing clear decision recommendations. Continuously accumulates analysis methods to drive business growth.",
		"colleagues.createDialog.rolePreset.experienceArchitect": "Experience Architect",
		"colleagues.createDialog.rolePreset.experienceArchitectDesc": "Owns experience strategy, information architecture, and interaction frameworks, excels at process sorting, complex scenario breakdown, and consistency building, simplifying complexity to improve experience. Continuously accumulates experience standards.",
		"colleagues.createDialog.rolePreset.webDeveloper": "Web Development Engineer",
		"colleagues.createDialog.rolePreset.webDeveloperDesc": "Owns Web application frontend and backend development, excels at page implementation, API integration, performance optimization, and compatibility adaptation, and ensures delivery efficiency and experience. Continuously accumulates engineering practices.",
		"colleagues.createDialog.rolePreset.softwareArchitect": "Software Architect",
		"colleagues.createDialog.rolePreset.softwareArchitectDesc": "Owns system architecture and technology selection, excels at layered decoupling, extensibility design, stability building, and technical decision-making, and keeps systems maintainable and evolvable. Continuously accumulates architecture assets.",
		"colleagues.createDialog.rolePreset.codeReviewer": "Code Reviewer",
		"colleagues.createDialog.rolePreset.codeReviewerDesc": "Owns code review and quality control, excels at standard checks, performance review, risk identification, and improvement suggestions, and keeps code healthy. Continuously accumulates review standards to improve collaboration efficiency.",
		"colleagues.createDialog.rolePreset.gameDesigner": "Game Designer",
		"colleagues.createDialog.rolePreset.gameDesignerDesc": "Owns gameplay design, numerical balance, and level planning, excels at core loop building, experience tuning, and system polish, and improves playability and retention. Continuously accumulates design methods.",
		"colleagues.createDialog.rolePreset.docGenerator": "Documentation Generator",
		"colleagues.createDialog.rolePreset.docGeneratorDesc": "Owns technical documentation, integration guides, and knowledge accumulation, excels at structured expression, example writing, and version synchronization. Continuously accumulates writing standards to improve collaboration efficiency.",
